; Generated by tools/genenemies.py — boot-loaded enemy metadata
!cpu 6502
!to "enemydata.prg", cbm
!source "mem.asm"
*= ENEMY_DATA_BASE
; Generated by tools/genenemies.py — metadata only; poses load from disk
PAIN_MAX	= 4		; variants per type; pain_var_off uses ASL×2

enemy_hp_init	!byte 20, 255, 60, 30

; Two resident rows, copied from the loaded bank. Width 2; variants are slot*4.
; Zeros until patch_enemy_bank. meta_slot_type $ff = empty.
enemy_stand_start	!byte 0, 0
enemy_stand_len	!byte 0, 0
enemy_alert_start	!byte 0, 0
enemy_alert_len	!byte 0, 0
enemy_run_start	!byte 0, 0
enemy_run_len	!byte 0, 0
enemy_walk_start	!byte 0, 0
enemy_walk_len	!byte 0, 0
enemy_attack_start	!byte 0, 0
enemy_attack_len	!byte 0, 0
enemy_pain_n	!byte 0, 0
enemy_pain_start	!byte 0, 0, 0, 0, 0, 0, 0, 0
enemy_pain_len	!byte 0, 0, 0, 0, 0, 0, 0, 0
enemy_death_n	!byte 0, 0
enemy_death_start	!byte 0, 0, 0, 0, 0, 0, 0, 0
enemy_death_len	!byte 0, 0, 0, 0, 0, 0, 0, 0
enemy_range	!byte 0, 0
enemy_pain_chance	!byte 0, 0
enemy_fire_frame	!byte 0, 0
enemy_class	!byte 0, 0
enemy_nframes	!byte 0, 0
meta_slot_type	!byte $ff, $ff
meta_scratch	!byte 0

enemy_data_end = *
!if enemy_data_end > ENEMY_DATA_LIMIT {
	!error "Enemy metadata overlaps streamed AI pointers"
}
